INSERT INTO `blog_posts` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `featured_image`, `author_name`, `author_role`, `tags`, `read_time`, `views`, `likes`, `status`, `created_by_admin_id`, `created_at`, `updated_at`) VALUES ('1', 'Top 7 Essential Vehicle Maintenance Tips for Long Drives', 'top-7-essential-vehicle-maintenance-tips', 'Vehicle Care', 'Preparing for an extended highway journey? Discover critical fluid checks, tire pressure recommendations, and battery maintenance before you hit the road.', '<h2>1. Check Engine Fluids Before Departure</h2><p>Before any major highway journey or road trip, inspecting engine oil levels, coolant, and brake fluid is paramount. Low or degraded fluid drastically increases friction and heat within the engine block.</p><h2>2. Inspect Tire Pressure & Tread Depth</h2><p>Tires are your vehicle\'s only contact point with the asphalt. Maintain manufacturer-recommended PSI levels (usually located on the driver-side door jamb sticker). Don\'t forget to inspect your spare tire!</p><h2>3. Test All Exterior Lights & Indicators</h2><p>Ensure headlights, high beams, taillights, brake lamps, and turn signals function flawlessly. In poor visibility, lighting is your primary safety mechanism.</p><h2>4. Schedule Doorstep Inspection with ServEasy</h2><p>Don\'t have time to visit an auto shop? ServEasy certified mobile mechanics will visit your home to conduct a comprehensive multi-point vehicle inspection at your convenience.</p>', './assets/images/blog-1.jpg', 'Marcus Sterling', 'Lead Automotive Specialist', 'Vehicle, Road Trip, Maintenance, Car Care', '4 min read', '145', '30', 'published', NULL, '2026-10-14 12:24:53', '2026-10-15 13:27:33');
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `featured_image`, `author_name`, `author_role`, `tags`, `read_time`, `views`, `likes`, `status`, `created_by_admin_id`, `created_at`, `updated_at`) VALUES ('2', 'Deep Home Sanitization: Beyond Basic Dusting and Sweeping', 'deep-home-sanitization-guide', 'Home & Living', 'Learn how professional hygiene teams sterilize high-touch surfaces, sanitize air ducts, and eradicate unseen allergens from living spaces.', '<h2>Understanding the Difference Between Cleaning & Sanitizing</h2><p>Regular surface wiping removes visible grime, but sanitization actively kills microscopic pathogens, bacteria, and allergens embedded in carpets, curtains, and upholstery.</p><h2>Target High-Touch Surfaces</h2><p>Door handles, light switches, cabinet pulls, remote controls, and kitchen countertops carry dense concentrations of everyday microbes. Use certified antimicrobial disinfectants.</p><h2>Bathroom & Kitchen Micro-Climate</h2><p>High moisture levels create ideal breeding grounds for mildew and spores. Professional steam cleaning delivers high temperature heat that sterilizes without damaging fragile tile grouting.</p><h2>Book Professional Cleaners</h2><p>ServEasy certified cleaners utilize medical-grade sanitizers and high-pressure steam extraction equipment for comprehensive home renewal.</p>', './assets/images/blog-2.jpg', 'Elena Rostova', 'Hygiene & Safety Consultant', 'Cleaning, Hygiene, Home Care, Sanitization', '6 min read', '105', '25', 'published', NULL, '2026-10-14 12:24:53', '2026-10-15 13:27:46');
INSERT INTO `blog_posts` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `featured_image`, `author_name`, `author_role`, `tags`, `read_time`, `views`, `likes`, `status`, `created_by_admin_id`, `created_at`, `updated_at`) VALUES ('3', 'Emergency Roadside Breakdown: A Step-by-Step Survival Checklist', 'emergency-roadside-breakdown-checklist', 'Emergency & Safety', 'Vehicle stalled in the middle of traffic or on a dark road? Here is how to keep yourself safe and dispatch emergency towing in minutes.', '<h2>Step 1: Steer to Safety Immediately</h2><p>If the engine starts sputtering or steam emerges, gently maneuver your vehicle onto the shoulder or a well-lit service bay. Avoid stopping on blind corners or high-speed lanes.</p><h2>Step 2: Activate Hazard Lights & Deploy Warning Triangles</h2><p>Alert approaching motorists by switching on hazard blinkers immediately. If safe, position reflective warning triangles 50 meters behind the vehicle.</p><h2>Step 3: Remain Inside or Behind Safety Barriers</h2><p>Never stand directly on highway lanes or between vehicles. Stay seated with seatbelts fastened or wait safely behind roadside guard rails.</p><h2>Step 4: Trigger ServEasy 24/7 SOS Dispatch</h2><p>Call our direct emergency line or use the 1-click Emergency SOS on the ServEasy app. Our closest mobile tow truck and technician will be dispatched to your GPS coordinate instantly.</p>', './assets/images/blog-3.jpg', 'David Chen', 'Emergency Dispatch Coordinator', 'Emergency, Breakdown, Towing, Roadside', '5 min read', '215', '51', 'published', NULL, '2026-10-14 12:24:53', '2026-10-14 12:33:59');
